
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_tm_lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_tm_lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.739046892831175e-02, -5.722877876981056e-02, -5.698733972681980e-02, -5.662073023544472e-02, -5.605028467308137e-02, -5.513032520120947e-02, -5.356690282309536e-02, -5.070186315232243e-02, -4.490170917622570e-02, -3.220079083912767e-02, -1.181402614309834e-02, -3.066291123578733e-02, -3.469691070479706e-02, -2.931266025941603e-02, -1.697457717469486e-02, -6.766031398123066e-04, 4.145674745911811e-04, -1.542308586669829e-03, -1.294263191052038e-04, -3.235781964991078e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


